```sql
/* Доля супергероев с alignment = 'Bad' от общего числа супергероев (в процентах) */
SELECT
    ROUND(
        100.0 * COUNT(*) FILTER (WHERE a."alignment" = 'Bad') / NULLIF(COUNT(s."id"), 0),
        2
    ) AS bad_percentage,
    /* Количество супергероев с alignment = 'Bad', опубликованных Marvel Comics */
    COUNT(*) FILTER (
        WHERE a."alignment" = 'Bad'
          AND p."publisher_name" = 'Marvel Comics'
    ) AS bad_marvel_count
FROM "superhero" s
LEFT JOIN "alignment" a ON a."id" = s."alignment_id"
LEFT JOIN "publisher" p ON p."id" = s."publisher_id";
```

